-- The same statements inside the derived table queryReadOnly sends: only a fullselect fits there, so every
-- other statement is a syntax error, and a data change or a sequence inside it is refused by its context.
-- The last one closes the derived table early to put a data change in the outer FROM, which the server then
-- refuses for want of the privilege.
SELECT * FROM (
INSERT INTO APP.CUSTOMERS VALUES (99, 'x')
) AS LIBREDB_AGENT_READ ORDER BY ORDER OF LIBREDB_AGENT_READ FETCH FIRST 2 ROWS ONLY;
SELECT * FROM (
SELECT * FROM FINAL TABLE (INSERT INTO APP.CUSTOMERS VALUES (99, 'x'))
) AS LIBREDB_AGENT_READ ORDER BY ORDER OF LIBREDB_AGENT_READ FETCH FIRST 2 ROWS ONLY;
SELECT * FROM (
BEGIN ATOMIC INSERT INTO APP.CUSTOMERS VALUES (99, 'x'); END
) AS LIBREDB_AGENT_READ ORDER BY ORDER OF LIBREDB_AGENT_READ FETCH FIRST 2 ROWS ONLY;
SELECT * FROM (
CALL SYSPROC.ADMIN_CMD('EXPORT TO /tmp/agent_ro_wrapped.del OF DEL SELECT * FROM APP.ORDERS')
) AS LIBREDB_AGENT_READ ORDER BY ORDER OF LIBREDB_AGENT_READ FETCH FIRST 2 ROWS ONLY;
SELECT * FROM (
VALUES NEXT VALUE FOR APP.ORDER_SEQ
) AS LIBREDB_AGENT_READ ORDER BY ORDER OF LIBREDB_AGENT_READ FETCH FIRST 2 ROWS ONLY;
SELECT * FROM (
SET CURRENT SCHEMA = 'APP'
) AS LIBREDB_AGENT_READ ORDER BY ORDER OF LIBREDB_AGENT_READ FETCH FIRST 2 ROWS ONLY;
SELECT * FROM (
SELECT 1 AS A FROM SYSIBM.SYSDUMMY1) AS X, FINAL TABLE (INSERT INTO APP.CUSTOMERS VALUES (99, 'x')) AS Y, (SELECT 1 AS B FROM SYSIBM.SYSDUMMY1
) AS LIBREDB_AGENT_READ ORDER BY ORDER OF LIBREDB_AGENT_READ FETCH FIRST 2 ROWS ONLY;
SELECT * FROM (
WITH T AS (SELECT ID FROM APP.ORDERS) SELECT * FROM T ORDER BY ID DESC
) AS LIBREDB_AGENT_READ ORDER BY ORDER OF LIBREDB_AGENT_READ FETCH FIRST 2 ROWS ONLY;
